using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------
var notes = new ResearchNotes();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (
            [Description("The search query to look up on the web")] string query
        ) =>
        {
            // Simulated web search returning relevant results for the query
            Console.WriteLine($"  🔍  Searching: {query}");
            return new[]
            {
                new SearchResult(
                    $"Introduction to {query}",
                    $"https://example.com/{Uri.EscapeDataString(query)}",
                    $"{query} is a broad topic with many facets. " +
                    "Recent research highlights significant developments in this area, " +
                    "including new methodologies and practical applications."),
                new SearchResult(
                    $"Latest advances in {query}",
                    $"https://research.example.com/{Uri.EscapeDataString(query)}",
                    $"Experts suggest that {query} will continue to evolve rapidly. " +
                    "Key trends include increased automation, improved accuracy, " +
                    "and wider adoption across industries."),
                new SearchResult(
                    $"{query} — practical guide",
                    $"https://guide.example.com/{Uri.EscapeDataString(query)}",
                    $"A hands-on overview of {query} covering best practices, " +
                    "common pitfalls, and real-world case studies from leading organizations."),
            };
        },
        "web_search",
        "Searches the web for information about a topic and returns a list of results with titles, URLs, and snippets."),

    AIFunctionFactory.Create(
        (
            [Description("A concise heading for the note")] string title,
            [Description("The body of the note (facts, quotes, observations)")] string content
        ) =>
        {
            notes.Add(title, content);
            Console.WriteLine($"  📝  Note saved: {title}");
            return $"Note \"{title}\" saved successfully.";
        },
        "save_note",
        "Saves a research note so you can reference it later when writing the summary."),

    AIFunctionFactory.Create(
        () =>
        {
            var all = notes.GetAll();
            Console.WriteLine($"  📋  Retrieved {all.Count} note(s)");
            return all;
        },
        "get_notes",
        "Retrieves all previously saved research notes."),
};

// --- Chat client via MEAI + OpenAI provider ----------------------------------
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation(o => o.MaximumIterationsPerRequest = 10)
    .Build();

// --- Agent -------------------------------------------------------------------
const string instructions = """
    You are a research assistant. When the user gives you a topic:

    1. Use the web_search tool 2-3 times with varied queries to gather information.
    2. After each search, use save_note to record the key findings.
    3. When you have enough material, use get_notes to review everything.
    4. Finally, write a well-structured summary with sections, citing sources by URL.

    Be thorough but concise. Always cite your sources.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    tools: tools);

// --- Interactive loop --------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════════════╗");
Console.WriteLine("║          🔬  Research Agent  (type 'exit' to quit)  ║");
Console.WriteLine("╚══════════════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    notes.Clear();
    Console.WriteLine();

    try
    {
        var session = await agent.CreateSessionAsync();

        var runOptions = new ChatClientAgentRunOptions
        {
            ChatOptions = new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            },
        };

        var response = await agent.RunAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            session,
            runOptions);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("━━━  Summary  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
        Console.ResetColor();
        Console.WriteLine(response.ToString());
        Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.Error.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// --- Supporting types --------------------------------------------------------

record SearchResult(string Title, string Url, string Snippet);

class ResearchNotes
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void Add(string title, string content) =>
        _notes.Add((title, content, DateTime.UtcNow));

    public List<object> GetAll() =>
        _notes.Select(n => (object)new { n.Title, n.Content, n.Timestamp }).ToList();

    public void Clear() => _notes.Clear();
}

